import hashlib,json
from pathlib import Path
from cmpilot.candidate_screening_v020 import validate_published_successor_ledger
from cmpilot.tptm.canonical import canonical_json_bytes
from cmpilot.tptm.review import review_decision_from_mapping,seal_review_decision,review_decision_payload,review_decision_bytes,validate_review_decision_bytes,validate_review_packet_bytes,second_review_requirement
R=Path('.'); run=R/'benchmark-selection/screening/runs/v0.2.0/run-09fafb41e8c4c29e4774ff9cc98027ed0630c2f4422ac801ea19bf19fdd24879'
def dig(p): return hashlib.sha256(p.read_bytes()).hexdigest()
def obj(p): return json.loads(p.read_bytes())
for side in sorted((R/'benchmark-selection/screening/operational-amendments').glob('*/operational-amendment.json.sha256'))+sorted((R/'benchmark-selection/screening/operational-amendments').glob('*/freeze-manifest.json.sha256')):
 p=side.with_suffix(''); assert dig(p)==side.read_text().split()[0],p
for fm in sorted((R/'benchmark-selection/screening/operational-amendments').glob('*/freeze-manifest.json')):
 d0=obj(fm)
 for key in ('artifacts','repository_artifacts','frozen_artifacts'):
  rows=d0.get(key,[])
  if isinstance(rows,list):
   for row in rows:
    if isinstance(row,dict) and isinstance(row.get('path'),str) and isinstance(row.get('sha256'),str) and not row['path'].startswith('/'):
     p=R/row['path']; assert p.exists() and dig(p)==row['sha256'],(fm,p)
proto=R/'benchmark-selection/screening/protocol/v0.2.0'
for side in sorted(proto.glob('*.sha256')):
 p=side.with_suffix(''); assert dig(p)==side.read_text().split()[0],p
ledger=obj(run/'ledger.json'); records=[obj(R/p) for p in ledger['record_paths']]; state=validate_published_successor_ledger(ledger,records)
assert dig(run/'ledger.json')==(run/'ledger.json.sha256').read_text().split()[0]; assert state.next_due_position==24 and state.records_published==23
pos=run/'positions/00000024'; auth=obj(pos/'position-authorization.json'); packet=validate_review_packet_bytes((pos/'review-packet.json').read_bytes()); a=obj(pos/'ai-reviewer-a-assignment.json'); d=obj(pos/'ai-reviewer-a-decision.json')
assert auth['queue_position']==24==a['queue_position']==d['queue_position']==packet.candidate_result.queue_position
assert len({auth['candidate_id'],a['candidate_id'],d['semantic_decision']['candidate_id'],packet.candidate_result.candidate_id})==1
assert dig(pos/'ai-reviewer-a-assignment.json')==d['assignment_sha256']; assert dig(pos/'review-packet.json')==d['review_packet_file_sha256']==a['review_packet']['file_sha256']; assert packet.review_packet_sha256==d['review_packet_sha256']==a['review_packet']['review_packet_sha256']
for mapping in (a['permitted_evidence_sha256'],a['permitted_interface_sha256']):
 for p,h in mapping.items(): assert dig(R/p)==h,p
sem=d['semantic_decision']; projection={'schema_version':'tptm-review-decision-v1','protocol_id':'tptm-hybrid-screening-v1','review_decision_sha256':None,'review_packet_sha256':sem['review_packet_sha256'],'candidate_id':sem['candidate_id'],'reviewer_role':'CODEX_PROPOSAL','human_action':'NOT_APPLICABLE','changed_question_ids':[],'focal_hypothesis':sem['focal_hypothesis'],'answers':sem['answers'],'outcome':sem['outcome'],'non_authoritative_commentary':sem['non_authoritative_commentary']}
typed=seal_review_decision(review_decision_from_mapping(projection)); assert validate_review_decision_bytes(review_decision_bytes(typed),packet)==typed
assert hashlib.sha256(canonical_json_bytes(review_decision_payload(typed))).hexdigest()==d['semantic_projection_sha256']; env={k:v for k,v in d.items() if k"'!='"'decision_sha256'}; assert hashlib.sha256(json.dumps(env,ensure_ascii=False,sort_keys=True,separators=(',',':')).encode()).hexdigest()==d['decision_sha256']
req=second_review_requirement(typed,packet.candidate_result)
print(json.dumps({'amendments_and_protocol_hashes':'PASS','ledger_checksum_replay':'PASS','due_position_identity':'PASS','ai_a_chain_and_canonical_projection':'PASS','reviewer_b_required':req.required,'reason':req.reason.value,'hash_bucket':req.hash_bucket},sort_keys=True))
PY"

